// Naive Python-base58-transliteration: repeated divmod by 58 / Horner.
const ALPHA = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
const B = 58n;
function encNaive(buf) {
  let orig = buf.length, i = 0;
  while (i < buf.length && buf[i] === 0) i++;
  const pad = i;
  let acc = 0n;
  for (let k = i; k < buf.length; k++) acc = acc * 256n + BigInt(buf[k]);
  let out = '';
  while (acc > 0n) { const d = acc % B; acc = acc / B; out = ALPHA[Number(d)] + out; }
  return ALPHA[0].repeat(pad) + out;
}
function decNaive(s) {
  let i = 0; while (i < s.length && s[i] === '1') i++;
  const pad = i;
  let acc = 0n;
  for (let k = i; k < s.length; k++) acc = acc * B + BigInt(ALPHA.indexOf(s[k]));
  const bytes = [];
  while (acc > 0n) { bytes.push(Number(acc % 256n)); acc = acc / 256n; }
  bytes.reverse();
  return Buffer.concat([Buffer.alloc(pad), Buffer.from(bytes)]);
}
const mode = process.argv[2], n = Number(process.argv[3]), ch = process.argv[4];
const t = Date.now();
let r;
if (mode === 'enc') r = encNaive(Buffer.from(ch.repeat(n)));
else r = decNaive(ch.repeat(n));
console.error(`naive ${mode} n=${n} ch=${ch} ms=${Date.now()-t} outlen=${r.length}`);
EOF
