const ALPHA = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
const IDX = new Int16Array(256).fill(-1);
for (let i = 0; i < 58; i++) IDX[ALPHA.charCodeAt(i)] = i;
const B = 58n;
// powers 58^(2^i)
const POW = [B];
function powUpTo(k) { while (POW.length <= k) POW.push(POW[POW.length-1] ** 2n); }

// ---- BigInt <-> bytes via hex (power-of-2 radix => linear in V8) ----
function bytesToBigInt(buf, start) {
  if (start >= buf.length) return 0n;
  const hex = buf.toString('hex', start);
  return BigInt('0x' + hex);
}
function bigIntToBytes(n) {
  if (n === 0n) return Buffer.alloc(0);
  let hex = n.toString(16);
  if (hex.length & 1) hex = '0' + hex;
  return Buffer.from(hex, 'hex');
}
// ---- BigInt -> base58 digit chars, divide & conquer ----
// writes exactly `width` digits (zero/'1'-padded) into out at [pos, pos+width)
function writeFixed(n, width, out, pos) {
  if (width === 1) { out[pos] = ALPHA.charCodeAt(Number(n)); return; }
  const half = width >> 1;          // low half gets `half` digits
  powUpTo(40);
  // need 58^half ; compute via table when half is a power of two, else pow
  const d = pow58(half);
  const hi = n / d, lo = n % d;
  writeFixed(hi, width - half, out, pos);
  writeFixed(lo, half, out, pos + width - half);
}
const powCache = new Map();
function pow58(k) {
  let v = powCache.get(k);
  if (v === undefined) { v = B ** BigInt(k); powCache.set(k, v); }
  return v;
}
function encodeInt(n) {
  if (n === 0n) return '';
  // digit count: use bit length estimate then correct
  const bits = n.toString(16).length * 4;
  let w = Math.max(1, Math.floor(bits / 5.857990) + 2);
  while (pow58(w) <= n) w++;
  while (w > 1 && pow58(w - 1) > n) w--;
  const out = Buffer.alloc(w);
  writeFixed(n, w, out, 0);
  return out.toString('latin1');
}
function b58encode(buf) {
  let i = 0; while (i < buf.length && buf[i] === 0) i++;
  return '1'.repeat(i) + encodeInt(bytesToBigInt(buf, i));
}
// ---- base58 digits -> BigInt, divide & conquer ----
function digitsToBigInt(codes, lo, hi) {           // [lo,hi)
  const n = hi - lo;
  if (n <= 0) return 0n;
  if (n <= 16) {
    let acc = 0n;
    for (let k = lo; k < hi; k++) acc = acc * B + BigInt(IDX[codes[k]]);
    return acc;
  }
  const half = n >> 1;
  const mid = hi - half;
  return digitsToBigInt(codes, lo, mid) * pow58(half) + digitsToBigInt(codes, mid, hi);
}
function b58decode(s) {
  let i = 0; while (i < s.length && s.charCodeAt(i) === 49) i++;
  const codes = Buffer.from(s, 'latin1');
  for (let k = 0; k < codes.length; k++) if (IDX[codes[k]] < 0) throw new Error('bad char');
  const n = digitsToBigInt(codes, i, codes.length);
  return Buffer.concat([Buffer.alloc(i), bigIntToBytes(n)]);
}
module.exports = { b58encode, b58decode, ALPHA };
EOF
cat > /tmp/w/repr.js <<'EOF'
// Python bytes repr
const HEX='0123456789abcdef';
function pyBytesRepr(buf) {
  let hasS=false, hasD=false;
  for (const c of buf) { if (c===39) hasS=true; else if (c===34) hasD=true; }
  const q = (hasS && !hasD) ? 34 : 39;
  const parts=[];
  for (let i=0;i<buf.length;i++){
    const c=buf[i];
    if (c===q||c===92) parts.push('\\'+String.fromCharCode(c));
    else if (c===9) parts.push('\\t');
    else if (c===10) parts.push('\\n');
    else if (c===13) parts.push('\\r');
    else if (c>=32 && c<127) parts.push(String.fromCharCode(c));
    else parts.push('\\x'+HEX[c>>4]+HEX[c&15]);
  }
  return "b"+String.fromCharCode(q)+parts.join('')+String.fromCharCode(q);
}
module.exports = { pyBytesRepr };
EOF
