// Adversarial boundary harness: compares reference binary vs Node port at/near MAX_ARG_STRLEN.
const {spawnSync} = require('child_process');
const REF = '/workspace/dataset/test15_executable';

function run(cmd, args) {
  const t = process.hrtime.bigint();
  const r = spawnSync(cmd, args, {maxBuffer: 1 << 30});
  const ms = Number(process.hrtime.bigint() - t) / 1e6;
  return {rc: r.status, out: r.stdout || Buffer.alloc(0), err: r.stderr || Buffer.alloc(0), ms};
}

function cmp(label, args) {
  const a = run(REF, args);
  const b = run('node', ['/tmp/w/main.js', ...args]);
  const ident = a.rc === b.rc && a.stdout === undefined ? false : (a.rc === b.rc && a.out.equals(b.out));
  const argbytes = args.map(x => Buffer.byteLength(x, 'utf8'));
  console.log(
    `${ident ? 'IDENT' : '*DIFF*'} | ${label}\n` +
    `        argBytes=[${argbytes.join(',')}] rc=${a.rc}/${b.rc} ` +
    `ref_ms=${a.ms.toFixed(0)} node_ms=${b.ms.toFixed(0)} speedup=${(a.ms/b.ms).toFixed(1)}x ` +
    `outBytes=${a.out.length}/${b.out.length} lines=${a.out.toString('latin1').split('\n').length - 1}`);
  if (!ident) {
    console.log('   refErr:', a.err.toString('latin1').slice(0, 300));
    console.log('   nodeErr:', b.err.toString('latin1').slice(0, 400));
    for (let i = 0; i < Math.max(a.out.length, b.out.length); i++)
      if (a.out[i] !== b.out[i]) { console.log(`   first diff at byte ${i}: ref=${a.out[i]} node=${b.out[i]}`); break; }
  }
  return ident;
}

const N = 131071;
const rep = (s, n) => s.repeat(n);
const cases = [];

// all-'1' decode: fastest path, produces N NUL bytes each
cases.push(['all-1 decode x2 (N=131071)', ['--a','x','--b','x','--c',rep('1',N),'--d',rep('1',N)]]);
// worst-case decode: 'z' = digit 57
cases.push(['all-z decode x2 (N=131071)', ['--a','x','--b','x','--c',rep('z',N),'--d',rep('z',N)]]);
// leading '1' run + max digits (padding + big number together)
cases.push(['65535x"1" + 65536x"z" decode x2', ['--a','x','--b','x',
  '--c',rep('1',65535)+rep('z',65536),'--d',rep('1',65535)+rep('z',65536)]]);
// high bytes via UTF-8 (byte length is what MAX_ARG_STRLEN limits, not char count)
cases.push(['UTF-8 2-byte U+00FF x65535 (131070 B)', ['--a',rep('ÿ',65535),'--b',rep('ÿ',65535),'--c','z','--d','z']]);
cases.push(['UTF-8 4-byte U+10FFFF x32767 (131068 B)', ['--a',rep('\u{10FFFF}',32767),'--b',rep('\u{10FFFF}',32767),'--c','z','--d','z']]);
// control/DEL bytes -> stresses \xNN repr expansion (4 chars per byte)
cases.push(['0x7f DEL x131071 encode x2', ['--a',rep('\x7f',N),'--b',rep('\x7f',N),'--c','z','--d','z']]);
// mixed random high-entropy printable ASCII
{
  let s = ''; for (let i = 0; i < N; i++) s += String.fromCharCode(33 + ((i * 7919) % 94));
  cases.push(['pseudorandom printable ASCII x131071', ['--a',s,'--b',s,'--c','z','--d','z']]);
}
// random base58 digits (high-entropy decode -> repr full of \xNN)
{
  const A = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
  let s = ''; for (let i = 0; i < N; i++) s += A[(i * 37 + 11) % 58];
  cases.push(['pseudorandom base58 decode x131071', ['--a','x','--b','x','--c',s,'--d',s]]);
}
// ALL FOUR maxed, worst case each
cases.push(['ALL FOUR maxed (a,b=0x7f; c,d=z)', ['--a',rep('\x7f',N),'--b',rep('\x7f',N),'--c',rep('z',N),'--d',rep('z',N)]]);

let ok = 0;
for (const [l, a] of cases) if (cmp(l, a)) ok++;
console.log(`\n${ok}/${cases.length} identical`);
